INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT146-S1-Q9$batch02$, 146, 1, 9, $batch02$Flaw$batch02$, $batch02$In a recent field study of prairie plants, the more plant species a prairie plot had, the more vigorously the plants grew and the better the soil retained nutrients. Thus, having more plant species improves a prairie’s ability to support plant life.$batch02$, $batch02$The argument is most vulnerable to criticism on the grounds that it$batch02$, $batch02$A$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=146 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q9$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$infers of two correlated phenomena, X and Y, that X causes Y without considering whether Y causes X$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q9$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$fails to describe the mechanism by which productivity is supposedly increased$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q9$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$takes for granted that the characteristics of one prairie plot could reveal something about the characteristics of other prairie plots$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q9$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$bases a general conclusion on data that is likely to be unrepresentative$batch02$, $batch02$Not Sampling$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q9$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$takes an increase in number to indicate an increase in proportion$batch02$, $batch02$Bad Description$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q9$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT146-S1-Q9$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$More plant species improve a prairie's ability to support plant life.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Plots with more species had more vigorous growth and better nutrient retention.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$More species goes with better growth and richer soil. The author says the species cause the good conditions. Try the reverse. Rich soil that holds nutrients can support more kinds of plants. Then the good conditions would cause the variety, not the other way around.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Expect the reverse-cause answer.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT146-S1-Q9$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The study shows a correlation between species count and a plot's ability to support plants. Good soil and growing conditions could be what allows more species to grow. The author assumes the direction runs from species to soil without considering the reverse.$batch02$), ($batch02$B$batch02$, $batch02$An argument can establish a cause without explaining how it works. Asking for the mechanism is not the flaw.$batch02$), ($batch02$C$batch02$, $batch02$The study compares many plots, and the conclusion is about prairies in general. Nothing hinges on one plot standing in for others.$batch02$), ($batch02$D$batch02$, $batch02$We are given no reason to think the plots studied were unusual.$batch02$), ($batch02$E$batch02$, $batch02$No proportions appear. The study counts species and measures growth.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT146-S1-Q9$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
